package com.lmspilot.reporting.domain;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;@Entity@Table(name="report_export_jobs",uniqueConstraints=@UniqueConstraint(name="uq_report_schedule_period",columnNames={"schedule_id","period_key"}),indexes={@Index(name="idx_report_export_owner",columnList="owner_id,created_at"),@Index(name="idx_report_export_status",columnList="status,created_at")})public class ReportExportJobEntity{@Id private UUID id=UUID.randomUUID();@Column(name="owner_id",nullable=false)private UUID ownerId;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private ReportScope scope=ReportScope.SELF;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private ReportExportStatus status=ReportExportStatus.PENDING;@Column(name="schedule_id")private UUID scheduleId;@Column(name="period_key",length=80)private String periodKey;@Column(name="output_csv",columnDefinition="text")private String outputCsv;@Column(name="row_count")private Integer rowCount;@Column(name="error_message",length=1000)private String errorMessage;@Column(name="created_at",nullable=false)private Instant createdAt=Instant.now();@Column(name="started_at")private Instant startedAt;@Column(name="completed_at")private Instant completedAt;@Column(name="expires_at",nullable=false)private Instant expiresAt=Instant.now().plusSeconds(604800);@Version private long version;public ReportExportJobEntity(){}public ReportExportJobEntity(UUID o,ReportScope s){ownerId=o;scope=s;}public ReportExportJobEntity(UUID o,ReportScope s,UUID sid,String pk){this(o,s);scheduleId=sid;periodKey=pk;}public UUID getId(){return id;}public UUID getOwnerId(){return ownerId;}public ReportScope getScope(){return scope;}public ReportExportStatus getStatus(){return status;}public void setStatus(ReportExportStatus v){status=v;}public UUID getScheduleId(){return scheduleId;}public String getPeriodKey(){return periodKey;}public String getOutputCsv(){return outputCsv;}public void setOutputCsv(String v){outputCsv=v;}public Integer getRowCount(){return rowCount;}public void setRowCount(Integer v){rowCount=v;}public String getErrorMessage(){return errorMessage;}public void setErrorMessage(String v){errorMessage=v;}public Instant getCreatedAt(){return createdAt;}public Instant getStartedAt(){return startedAt;}public void setStartedAt(Instant v){startedAt=v;}public Instant getCompletedAt(){return completedAt;}public void setCompletedAt(Instant v){completedAt=v;}public Instant getExpiresAt(){return expiresAt;}}
